import { z } from "zod"
import type { CustomerType, ResearchJob, StartResearchResponse } from "@/types/research"

const CUSTOMER_TYPES = ["B2B", "B2C", "Enterprise"] as const satisfies readonly CustomerType[]

/**
 * Runtime validation for responses from n8n.
 *
 * The job envelope is strict: if it is malformed, the integration is broken
 * and we want a clear error. Fields generated by an LLM are lenient: a missing
 * or malformed value falls back to null/[] instead of failing the whole result.
 */

const str = z.string().nullable().catch(null)
const strList = z.array(z.string()).catch([])
const icpTier = z.enum(["High Fit", "Moderate Fit", "Low Fit", "Needs Review"])

const companyFacts = z.union([
  z.object({
    company_name: str,
    value_proposition: str,
    products_and_services: strList,
    target_industries: strList,
    // Keep recognised values; drop anything else the model invents
    customer_types: strList.transform((list) =>
      list.filter((t): t is CustomerType => (CUSTOMER_TYPES as readonly string[]).includes(t)),
    ),
    headquarters_locations: strList,
    detected_technologies: strList,
  }),
  z.object({ raw: z.string() }),
])

const synthesizedResearch = z.object({
  company_name: z.string().catch(""),
  domain: z.string().catch(""),
  summary: z.string().catch(""),
  confirmed_facts: z.array(z.object({ fact: z.string(), source: z.string().catch("") })).catch([]),
  reasonable_inferences: z
    .array(z.object({ inference: z.string(), basis: z.string().catch("") }))
    .catch([]),
  unknowns: strList,
  recent_signals: z
    .array(
      z.object({
        signal: z.string(),
        source_url: z.string().catch(""),
        date: str,
      }),
    )
    .catch([]),
})

const icpCriterion = z.object({
  criterion: z.string(),
  score: z.number(),
  max: z.number(),
  status: z.enum(["met", "not_met", "unknown"]),
  reason: z.string().catch(""),
})

const companyResearchRecord = z.object({
  id: z.number(),
  domain: z.string(),
  status: z.enum(["validated", "error/unreachable"]),
  updated_at: z.string(),
  company_facts: companyFacts.nullable().catch(null),
  research_signals: z
    .object({ results: z.array(z.object({ title: z.string().catch(""), url: z.string() })) })
    .nullable()
    .catch(null),
  synthesized_research: synthesizedResearch.nullable().catch(null),
  sources: z.object({ urls: strList }).nullable().catch(null),
  icp_score: z.number().nullable().catch(null),
  icp_tier: icpTier.nullable().catch(null),
  icp_breakdown: z.array(icpCriterion).nullable().optional().catch(null).transform((v) => v ?? null),
  account_brief: str,
})

export const startResearchResponseSchema = z.object({
  job_id: z.string().min(1),
  duplicate: z.boolean().catch(false),
}) satisfies z.ZodType<StartResearchResponse>

export const researchJobSchema = z.object({
  job_id: z.string().min(1),
  status: z.enum(["running", "completed", "cached", "unreachable", "not_found", "failed"]),
  input: z.string(),
  domain: z.string().nullable(),
  error: z.string().nullable(),
  created_at: z.string(),
  updated_at: z.string(),
  record: companyResearchRecord.nullable(),
}) satisfies z.ZodType<ResearchJob>
